func TestConcurrentAccess(t *testing.T) {
	clock := newFakeClock(time.Unix(0, 0))
	l, _ := New(1000, 100, clock)
	var wg sync.WaitGroup
	allowed := int64(0)
	var mu sync.Mutex
	for i := 0; i < 50; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := 0; j < 10; j++ {
				if l.AllowN(clock.Now(), 1) {
					mu.Lock()
					allowed++
					mu.Unlock()
				}
			}
		}()
	}
	wg.Wait()
	if allowed != 100 {
		t.Errorf("allowed = %d, want 100", allowed)
	}
}
